#!/bin/bash
# Rebuilds payments.html from the generated partials.
#
# The body is generated by _gen_payments.py from the twenty-section
# specification, so every numbered sub-item (1.1 … 20.10 = 210 panels) is
# present by construction and the figures stay consistent across sections.
set -e
cd "$(dirname "$0")"

python3 _gen_payments.py
cat _payments.css _payments2.css > _payments-build.css
python3 _compose.py _pm2head.html payments _payments-build.css

{
  cat _pm2head.html
  cat _pm2body.html
  cat _pm2js.js
  printf '</body>\n</html>\n'
} > payments.html

python3 - <<'PY'
import pathlib
p = pathlib.Path('payments.html')
s = p.read_text()
s = s.replace('<title>Module — GOLDEN FINANCIAL SERVICES</title>',
              '<title>Methods of Payment Management &amp; Connections — GOLDEN FINANCIAL SERVICES</title>')
p.write_text(s)
print('built payments.html', len(s), 'bytes')
PY

python3 inject_backnav.py payments.html
